b=Path('docs/PROJECT-BOARD.html'); bp=split_snapshot(b.read_text(encoding='utf-8')); before=json.loads(bp[1]); now=datetime.now(timezone.utc).isoformat()
rules=[
('RQ1','Authority','Authenticate actual caller/window and current owner before looking up a request. UI-supplied owner/session/digest never grants authority. Rejected caller cannot discover another owner result.'),
('RQ2','Identity','Proposed key is runtime-epoch + trusted owner session + draft-id + operation + request-id. Operation is save or finalize. Native selection must already be bound to that owner. Exact issuer and owner DTO remain separate S3-G1/G2 decisions.'),
('RQ3','Fingerprint','Compare the exact immutable typed request capture: expected revision, draft content, resolved target selection identity and prepared preference plan identity. Capture is server-owned; compare typed values, not raw JSON byte order or caller-supplied hash. Same key with changed capture is REQUEST_ID_CONFLICT.'),
('RQ4','Reservation','Validate authority, selection and request shape, then atomically reserve the key with its capture before starting S2 store. Concurrent identical submissions observe IN_FLIGHT and do not execute a second store. Do not hold owner map locks across IO.'),
('RQ5','Replay','Identical retained terminal capture returns the stored original outcome including commit proof; mark replayed=true. It does not re-run IO or acknowledge a newer revision. Same key with different capture is rejected even if original operation failed.'),
('RQ6','Terminal failure','Pre-commit failure, conflict, Partial and RecoveryRequired are terminal stored outcomes, preserving the exact S2 distinction. Explicit retry requires a fresh request-id after owner refresh. Never convert committed or recovery-required evidence into ordinary unchanged failure.'),
('RQ7','Late completion','On completion persist the terminal outcome in the retained request record before attempting UI projection. Owner switch/window closure only detaches presentation. It must not cancel or delete an already committed project. Binding is allowed only when captured owner epoch, request, draft and revision still match current authorization.'),
('RQ8','Lifetime','Propose runtime-only records, retained until process exit without time-based eviction. Owner close revokes ability to replay; retain tombstone/result for internal completion only. No exactly-once claim across restart. Old epoch is rejected; reopen via S2 evidence and issue a new request after explicit reconciliation.'),
('RQ9','Bounded resources','Propose at most 128 reserved request keys per owner and 1024 per process, including retained terminal keys. Refuse a new key with REQUEST_CAPACITY before IO; existing authorized replay remains available. No automatic eviction/retry or new persistent journal.'),
('RQ10','Result projection','Proposed transport fields: requestId, operation, capturedRevision decimal string, outcome, replayed boolean, bindingStatus. outcome wraps exact adopted S2 result without discarding evidence; bindingStatus is unchanged, eligible or detached. Eligible is not itself proof a UI switch occurred. Exact DTO/error mapping remains S3-G5 work.')]
vectors=[
('same_inflight','same','running','current','IN_FLIGHT',0,False),('changed_inflight','changed','running','current','REQUEST_ID_CONFLICT',0,False),
('same_committed','same','committed','current','original committed outcome',0,False),('changed_committed','changed','committed','current','REQUEST_ID_CONFLICT',0,False),
('same_failed','same','precommit_failed','current','original failure',0,False),('same_partial','same','partial','current','original partial evidence',0,False),
('same_recovery','same','recovery_required','current','original recovery evidence',0,False),('foreign_owner','same','committed','foreign','UNAUTHORIZED',0,False),
('stale_epoch','same','committed','expired','STALE_OWNER',0,False),('capacity','new','absent_full','current','REQUEST_CAPACITY',0,False),
('late_committed','same','completing_commit','detached','committed / detached',0,False),('new_request','new','absent','current','reserve then invoke S2 once',1,False)]
tests=[{'id':f'S3-RQ-{i+1:02d}','fixture':{'case':v[0],'capture':v[1],'record':v[2],'authority':v[3]},'oracle':{'result':v[4],'additional_store_calls':v[5],'automatic_project_switch':v[6]},'status':'PLANNED_NOT_RUN'} for i,v in enumerate(vectors)]
m={'module':'M01','slice':'S3 request coordination proposal','status':'PROPOSED_PENDING_OWNER_NOT_READY_FOR_IMPLEMENTATION','at':now,'intent':'Prevent duplicate persistence and unauthorized late current-project switches without changing S2 storage semantics.','assumptions':['Trusted owner/selection issuance will be specified separately; these rules do not approve that architecture.','Runtime-only deduplication is a new proposed S3 policy, not existing behavior or durable exactly-once guarantee.'],'rules':[{'id':a,'name':c,'contract':d} for a,c,d in rules],'architecture':{'hexagonal':'UI -> authenticated Tauri command -> DispatchHost request coordination -> adopted S1/S2 -> existing IO Port','dependencies':'Native picker -> trusted owner-bound selection; HOST captures immutable request; S2 owns persistence outcome; UI consumes authorized projection','ownership':'HOST owns runtime request records; domain owns definition; IO owns private journal; no new global manager or persistence store.','transaction':'Reserve immutable capture -> S2 store -> retain terminal proof -> independently authorize UI binding. IO transaction boundary unchanged.','forbidden':['UI filesystem/adapters','HOST writes private IO journal','rollback committed project on UI detach','new domain ownership or S2 error semantics']},'decisions':[{'id':'M01-S3-RQ-D1','proposal':'RQ1-RQ7 capture/reservation/replay/late-completion rules'},{'id':'M01-S3-RQ-D2','proposal':'RQ8 runtime-only retention and no across-restart exactly-once'},{'id':'M01-S3-RQ-D3','proposal':'RQ9 capacity 128 per owner / 1024 process; reject without IO'}],'tests':tests,'bdd_categories':{f'B{i}':'Applicable: request coordination contract; broader module coverage remains in parent packet' for i in range(1,13)},'candidate_files':['apps/sgenaxis-desktop/src-tauri/src/dispatch.rs','apps/sgenaxis-desktop/src-tauri/src/dto.rs','apps/sgenaxis-desktop/src-tauri/tests/phase1_project_definition_commands.rs'],'scope':'Only planning files and own card evidence changed; candidate product files are not approved by this delivery.','remaining':['S3-G1 actual authenticated caller and native capability issuer','S3-G2 complete owner and draft lifecycle','S3-G5 exact DTO/error/permission and all three caller migration','Complete six-step UI schema and integration fixtures; consolidate one full Owner review package'],'test_gate':'After full architecture adoption, tests must compile and fail for missing promised behavior; fixture/environment failures are not RED.','verification':{'source_unchanged':len(base['source_hashes']),'branch':base['branch'],'head':base['head'],'product_tests':'NOT RUN','native':'NOT RUN','build':'NOT RUN','independent_acceptance':'NOT RUN'}}
write('module-spec.json',m);write('fixtures-and-oracles.json',tests)
feature='Feature: M01 request replay and detached completion\n  # Proposed only; no executable RED or approved new architecture\n  Background:\n    Given an authenticated owner and an immutable request capture\n'
for t in tests: feature+=f"\n  Scenario: {t['id']} {t['fixture']['case']}\n    Given request record is {t['fixture']['record']}\n    And caller authority is {t['fixture']['authority']}\n    When the {t['fixture']['capture']} capture is submitted\n    Then result is {t['oracle']['result']}\n    And additional persistence calls equal {t['oracle']['additional_store_calls']}\n    And no automatic project switch occurs\n"
(O/'module.feature').write_text(feature,encoding='utf-8')
body='<h1>M01-S3 去重與延遲完成契約提案</h1><p>PROPOSED／待整包確認。這是 S3-G3/G4 的精確化子包，不是完整 S3 或已核准 Skeleton。</p><h2>意圖與假設</h2><p>同一請求不重複保存；延遲成功不能越權切換目前專案。native capability、實際 caller 與 owner 生命週期仍需另包精確化。</p><h2>架構與交易</h2>'
body+='<pre>'+html.escape(m['architecture']['hexagonal']+'\n'+m['architecture']['dependencies']+'\n'+m['architecture']['transaction'])+'</pre><p>'+html.escape(m['architecture']['ownership'])+'</p><h2>契約與待採納決策</h2>'
body+=''.join('<p><b>'+a+' '+c+'</b><br>'+html.escape(d)+'</p>' for a,c,d in rules)
body+='<h2>BDD／TDD 與 fixtures</h2><p>12 個具體狀態／結果／額外 IO 次數 oracle，全部 PLANNED／NOT RUN。首次成功與 UI 綁定完整測試仍在整包待補範圍。</p><table>'+''.join('<tr><td>'+t['id']+'</td><td>'+t['fixture']['case']+'</td><td>'+html.escape(t['oracle']['result'])+'</td><td>'+str(t['oracle']['additional_store_calls'])+'</td></tr>' for t in tests)+'</table>'
body+='<h2>範圍、驗收與風險</h2><p>只寫 M01 planning 與本卡證據。796 產品來源 SHA、branch／HEAD 核對一致；產品測試、build、native 均 NOT RUN。runtime 去重不提供跨程序 exactly-once；容量與保存生命週期為新建議，尚未採納。</p><h2>下一步</h2><ul>'+''.join('<li>'+html.escape(x)+'</li>' for x in m['remaining'])+'</ul><p>M01 PREP 維持黃燈；S1/S2 已接受成果不重開。完成完整精確包後一次供 Owner 確認，不能以此子包自開 Skeleton。</p>'
(O/'index.html').write_text('<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><title>M01 S3 request contract</title><style>body{max-width:1100px;margin:40px auto;font:16px system-ui;line-height:1.6}pre{white-space:pre-wrap}td{border:1px solid #ccc;padding:8px}</style>'+body+'<script type="application/json" id="module-spec">'+json.dumps(m,ensure_ascii=False).replace('</','<\\/')+'</script></html>',encoding='utf-8')
state=load(P/'current-state.json');state['s3_request_proposal']={'status':m['status'],'report':'s3-request-contract/index.html','decisions':[d['id'] for d in m['decisions']]};state['next_step']='Consolidate S3 precise native selection/owner lifecycle/DTO permissions/UI migration packet; request proposal is unapproved, no Skeleton yet.';(P/'current-state.json').write_text(json.dumps(state,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
report=str((O/'index.html').relative_to(Path.cwd())).replace('\\','/')
def change(s):
 t=next(t for t in s['tasks'] if t['id']=='PD-P1-M01-PREP-01');t['s3RequestProposal']={'status':m['status'],'report':report,'at':now};t['nextStep']=state['next_step'];t['notes']=t.get('notes','')+'\n['+now+'] S3 request proposal delivered: 10 rules, 12 fixture/oracle plans; runtime-only retention/capacity are proposed, not approved. Product unchanged. '+report
